<?php defined('ABSPATH') || exit;
if (isset($_GET['edit'])) { $id = absint($_GET['edit']); $company = $id ? get_post($id) : null;
    if ($id && (!$company || $company->post_type !== 'tj_company')) { tj_empty('Company not found'); return; }
    echo '<section class="tj-panel">'; tj_form_start('save_company', 'tj-stack'); tj_hidden('id', $id); echo '<div class="tj-form-grid">'; tj_input('title', tj_t('Tên công ty (Việt)', 'Company name (Vietnamese)'), $company->post_title ?? '', 'text', true); tj_input('title_en', 'Company name (English)', tj_meta($id, 'title_en')); tj_input('location', tj_t('Địa điểm', 'Location'), tj_meta($id, 'location')); tj_input('website', 'Website', tj_meta($id, 'website'), 'url'); tj_editor('description', tj_t('Giới thiệu (Việt)', 'About (Vietnamese)'), $company->post_content ?? ''); tj_editor('description_en', 'About (English)', tj_meta($id, 'description_en')); echo '</div>'; ?><label class="tj-check"><input type="checkbox" name="featured" value="1" <?php checked(tj_meta($id, 'featured')); ?>> <?php tj_e('Công ty nổi bật', 'Featured company'); ?></label><?php tj_button(); echo '</form></section>';
} else { ?><p><a class="tj-button" href="<?php echo esc_url(tj_url('quan-tri/cong-ty', ['edit' => 'new'])); ?>">+ <?php tj_e('Thêm công ty', 'Add company'); ?></a></p><div class="tj-table-wrap"><table class="tj-table"><thead><tr><th><?php tj_e('Công ty', 'Company'); ?></th><th><?php tj_e('Địa điểm', 'Location'); ?></th><th></th></tr></thead><tbody><?php foreach (get_posts(['post_type' => 'tj_company', 'numberposts' => -1]) as $company) { ?><tr><td><?php echo esc_html(tj_title($company->ID)); ?></td><td><?php echo esc_html(tj_meta($company->ID, 'location')); ?></td><td><div class="tj-row"><a href="<?php echo esc_url(tj_url('quan-tri/cong-ty', ['edit' => $company->ID])); ?>"><?php tj_e('Sửa', 'Edit'); ?></a><?php tj_form_start('delete_company', 'tj-inline tj-confirm'); tj_hidden('id', $company->ID); tj_button('Xóa', 'Delete', 'danger'); echo '</form>'; ?></div></td></tr><?php } ?></tbody></table></div><?php }
